import { createHandoff } from '@projexlight/sdk-handoff';

const handoff = await createHandoff({
  tenant_id: req.auth.tenant_id,
  from_persona_id: req.auth.sub,
  deal_id: dealId,
  cs_owner_persona_id: csOwnerId,
  promises: [{ text: 'Go-live within 30 days' }],
  risks: [{ text: 'Legacy data migration' }],
});
console.log(handoff.status); // 'draft'

import { transitionHandoff, InvalidHandoffTransition } from '@projexlight/sdk-handoff';

try {
  await transitionHandoff(tenantId, handoffId, 'pending');   // draft -> pending
  await transitionHandoff(tenantId, handoffId, 'accepted');  // pending -> accepted
  const done = await transitionHandoff(tenantId, handoffId, 'completed');
  console.log(done?.completed_at);
} catch (err) {
  if (err instanceof InvalidHandoffTransition) console.error(err.message);
}

import { startHandoffSaga, listHandoffSagaSteps } from '@projexlight/sdk-handoff';

const run = await startHandoffSaga(tenantId, handoffId);
console.log(run.run_id, run.status, run.phases);

const steps = await listHandoffSagaSteps(tenantId, handoffId);
// each: { phase, status: 'done' | 'compensated', run_id, created_at }

import { requestHandoffApproval, recordHandoffDecision } from '@projexlight/sdk-handoff';

await requestHandoffApproval(tenantId, handoffId); // draft -> pending, files the approval

// once CS decides:
const rec = await recordHandoffDecision(tenantId, handoffId, 'approved');
console.log(rec?.status); // 'accepted'
